ProjectALife.DialogueShards["scenes_any_2"] = {
{"fw_ld4_culture_a_0012","any",2,"reg=civilian,family,worker,rescue|tmp=fresh",{1,"I was gonna see a concert in August",2,"Who?",1,"Doesn't matter, I had tickets, third row",2,"Did you keep them?",1,"In my wallet, I look at them when I can't sleep"}},
{"fw_ld4_culture_a_0013","any",2,"reg=civilian,family,worker,rescue|tmp=fresh",{1,"What's your favorite cartoon?",2,"The Saturday morning ones",1,"With cereal in front of the TV?",2,"In my pajamas, with my brother, fighting over the remote",1,"I miss the fighting"}},
{"fw_ld4_culture_a_0014","any",2,"reg=law,swat",{1,"Back at the academy, they showed us a film about a cop who dies a week before retirement",2,"Classic",1,"Everyone cried, I cried the hardest",2,"And now you're a week from retirement",1,"Don't remind me"}},
{"fw_ld4_culture_a_0015","any",2,"reg=law,swat",{1,"Everyone thinks cops watch cop shows",2,"We don't?",1,"I watch the fishing channel",2,"There's a fishing channel?",1,"There WAS a fishing channel"}},
{"fw_ld4_culture_a_0016","any",2,"reg=military,elite",{1,"What music do you listen to?",2,"Whatever's on the boombox, mostly old country",1,"I'm a rock guy",2,"Of course you are, you're 20",1,"22, and I've got taste"}},
{"fw_ld4_culture_a_0017","any",2,"reg=military,elite",{1,"Heard the president's coming to Fort Knox",2,"When?",1,"Soon, they say",2,"They said that in March",1,"They said that every March"}},
{"fw_ld4_culture_a_0018","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"Last good meal I had was a steak at a roadhouse in Bardstown",2,"With a beer?",1,"With three, a baked potato, the works",2,"And then?",1,"And then I stole the tip jar and left, simpler times"}},
{"fw_ld4_culture_a_0019","any",2,"reg=family",{1,"Do you remember Sunday dinners at Grandma's?",2,"Fried chicken, biscuits, green beans cooked with fatback",1,"And the pie",2,"Always the pie, three kinds",1,"I'd trade my right arm for a slice"}},
{"fw_ld4_culture_a_0020","any",2,"reg=family",{1,"Papa used to listen to the Reds on the radio",2,"Every game?",1,"Every single one, and he'd shout at the radio like it could hear him",2,"Did it ever answer?",1,"No, but he never stopped"}},
{"fw_ld4_culture_a_0021","any",2,"reg=family",{1,"Mama, sing the lullaby",2,"Which one, baby?",1,"The one about the little bird",2,"Hush, little baby, don't say a word...",1,"Mama's gonna buy you a mockingbird..."}},
{"fw_ld4_food_a_0001","any",2,"reg=civilian,family,worker,rescue",{1,"What's for supper?",2,"What do you think?",1,"Beans?",2,"Beans with a side of beans",1,"My favorite",2,"Don't be sarcastic, I got you a pickle"}},
{"fw_ld4_food_a_0002","any",2,"reg=civilian,family,worker,rescue",{1,"I would sell my soul for a cheeseburger",2,"With fries?",1,"And a milkshake, chocolate, thick enough to need a spoon",2,"Stop, I'm drooling",1,"Imagine the first bite"}},
{"fw_ld4_food_a_0003","any",2,"reg=civilian,family,worker,rescue",{1,"Anyone else dream about food?",2,"Every night",1,"Last night I dreamed about my aunt's chicken and dumplings",2,"Did you eat them?",1,"I woke up just as the fork reached my mouth",2,"That's the cruelest thing I've ever heard"}},
{"fw_ld4_food_a_0004","any",2,"reg=civilian,family,worker,rescue",{1,"Look what I found",2,"A can of peaches!",1,"Syrup and everything, split it?",2,"Three ways, there's three of us",1,"Okay, but I get the juice"}},
{"fw_ld4_food_a_0005","any",2,"reg=civilian,family,worker,rescue",{1,"Tuna again?",2,"There was salmon yesterday",1,"Salmon tastes like regret",2,"Tuna tastes like regret with mayo, and we don't have mayo"}},
{"fw_ld4_food_a_0006","any",2,"reg=civilian,family,worker,rescue",{1,"Don't eat that, it's expired",2,"It's only three months",1,"Three months is a lot of months",2,"I'm hungry enough to eat the label"}},
{"fw_ld4_food_a_0007","any",2,"reg=civilian,family,worker,rescue",{1,"What's your comfort food?",2,"Mac and cheese, the blue box",1,"Mine's grilled cheese, with tomato soup",2,"Okay, stop, we're making each other sad"}},
{"fw_ld4_food_a_0008","any",2,"reg=civilian,family,worker,rescue",{1,"Smell that?",2,"What?",1,"Somebody's cooking something",2,"Meat?",1,"Maybe, God, my mouth is watering",2,"Don't follow it, it could be a trap",1,"I KNOW, but it smells so good"}},
{"fw_ld4_food_a_0009","any",2,"reg=civilian,family,worker,rescue",{1,"I never thought I'd say this, but I miss vegetables",2,"Real ones?",1,"A salad, a crunchy salad, with ranch dressing",2,"Lettuce, I miss lettuce",1,"Now I'm just a bunch of nouns, missing things"}},
{"fw_ld4_food_a_0010","any",2,"reg=civilian,family,worker,rescue",{1,"You're hogging the crackers",2,"I'm sharing",1,"You've got twelve and I've got two",2,"You eat slower, it evens out",1,"That's not how math works"}},
{"fw_ld4_food_a_0011","any",2,"reg=civilian,family,worker,rescue",{1,"Share a candy bar?",2,"Which kind?",1,"Snickers",2,"OH MY GOD, yes- gimme!",1,"Calm down, it's small",2,"It's the best thing that's ever happened to me this week"}},
{"fw_ld4_food_a_0012","any",2,"reg=civilian,family,worker,rescue",{1,"Do you know how to cook anything besides canned stuff?",2,"I can fry an egg",1,"Do you have an egg?",2,"...no, but I can fry an egg",1,"Good to know"}},
{"fw_ld4_food_a_0013","any",2,"reg=civilian,family,worker,rescue",{1,"Dad used to make pancakes on Sunday",2,"What kind?",1,"Buttermilk, with real maple syrup, and a little bacon on the side",2,"That's it, I'm crying, you did this"}},
{"fw_ld4_food_a_0014","any",2,"reg=civilian,family,worker,rescue",{1,"This tastes like feet",2,"It's supposed to be stew",1,"It's supposed to be but it isn't",2,"Eat it anyway, we're rationing"}},
{"fw_ld4_food_a_0015","any",2,"reg=civilian,family,worker,rescue",{1,"Would you keep a fork if one of the prongs broke?",2,"Why?",1,"I broke one once. Kept telling myself it was still a fork",2,"I'd have kept it. I've eaten with a spoon, a knife, and my hands"}},
{"fw_ld4_food_a_0016","any",2,"reg=civilian,family,worker,rescue|hour=6,11",{1,"Breakfast?",2,"Half a can of fruit cocktail",1,"The one with the cherry?",2,"There's always a cherry, and it's always mine",1,"Selfish",2,"I'm hungry"}},
{"fw_ld4_food_a_0017","any",2,"reg=civilian,family,worker,rescue|hour=19,22",{1,"Supper's ready",2,"What is it?",1,"Surprise",2,"I hate surprises",1,"It's soup, it's always soup"}},
{"fw_ld4_food_a_0018","any",2,"reg=family",{1,"Who made this?",2,"I did, with Grandma's recipe",1,"It tastes just like hers",2,"That's because I used her pot"}},
{"fw_ld4_food_a_0019","any",2,"reg=family",{1,"Clean your plate",2,"There's only a spoonful",1,"Then clean the spoonful",2,"It's gone, Mama",1,"Good boy"}},
{"fw_ld4_food_a_0020","any",2,"reg=family",{1,"Pass the salt",2,"There's no salt",1,"Pass the pepper",2,"There's no pepper",1,"Pass the... whatever",2,"Here, hot sauce, last bottle"}},
{"fw_ld4_food_a_0021","any",2,"reg=law,swat",{1,"Anything good in the break room?",2,"A box of tea bags and a petrified donut",1,"I'll take the donut",2,"It's fossilized",1,"Fossilized or not, it's a donut"}},
{"fw_ld4_food_a_0022","any",2,"reg=law,swat",{1,"Last night's casserole is gone",2,"Of course it's gone, it was the best thing we've had",1,"Who made it?",2,"Dispatch, God bless her"}},
{"fw_ld4_food_a_0023","any",2,"reg=military,elite",{1,"Which MRE is the best?",2,"Chili mac",1,"No, the spaghetti",2,"Okay, the spaghetti, but only because of the cheese spread",1,"The cheese spread is life"}},
{"fw_ld4_food_a_0024","any",2,"reg=military,elite",{1,"What's in this?",2,"Don't ask",1,"I'm asking",2,"Beef, and something that used to be beef"}},
{"fw_ld4_food_a_0025","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"Anybody got hot sauce?",2,"I've got ketchup",1,"That's not hot sauce",2,"It's red, it's a sauce, close enough"}},
{"fw_ld4_food_a_0026","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"Ever had somebody tell you squirrel was rabbit?",2,"Squirrel's food too",1,"Squirrel? I don't eat squirrel",2,"You might change your mind if you were hungry",1,"I'd still want to know before I took a leg"}},
{"fw_ld4_grief_a_0001","any",2,"reg=civilian,family,worker,rescue|world=cold",{1,"Is that his jacket?",2,"Yeah, I couldn't leave it, it still smells like him",1,"Put it on, it's cold",2,"It's too big, he was a big man, huh",1,"He was a big man with a big heart, wear it"}},
{"fw_ld4_grief_a_0002","any",2,"reg=civilian,family,worker,rescue|hour=16,5",{1,"I keep setting a place for her",2,"Oh, Ruth",1,"I know, I KNOW, it's stupid, I just look down and there's a plate",2,"It's not stupid, take it away if you want, or leave it, whichever helps",1,"I'll leave it tonight, just tonight"}},
{"fw_ld4_grief_a_0003","any",2,"reg=civilian,family,worker,rescue",{1,"Sorry about Danny",2,"Thanks",1,"He was the funniest guy I ever met",2,"He once put a whoopee cushion on a deputy's seat",1,"At his own wedding rehearsal!",2,"...God, I miss him, I miss him so much"}},
{"fw_ld4_grief_a_0004","any",2,"reg=civilian,family,worker,rescue",{1,"I should've gone back for her",2,"You couldn't have, they were everywhere",1,"I could've tried",2,"And died, and then what, we'd both be dead",1,"Maybe that'd be better than this"}},
{"fw_ld4_grief_a_0005","any",2,"reg=civilian,family,worker,rescue",{1,"I don't know how to be sad right now",2,"You don't have to know",1,"It's like there's a wall, I can see the other side, but I can't get through",2,"It'll break, it breaks when you're not looking",1,"When? When does it break?"}},
{"fw_ld4_grief_a_0006","any",2,"reg=civilian,family,worker,rescue",{1,"Do you think he suffered?",2,"No",1,"You didn't see it, how can you say no?",2,"Because I need you to believe it, and I need to believe it too",1,"...okay, okay, we'll both believe it"}},
{"fw_ld4_grief_a_0007","any",2,"reg=civilian,family,worker,rescue",{1,"Say her name",2,"Susan",1,"Again",2,"Susan Marie Caldwell, born April 3rd, 1961",1,"Thank you, thank you, I needed to hear someone else say it"}},
{"fw_ld4_grief_a_0008","any",2,"reg=civilian,family,worker,rescue|world=trees",{1,"I buried him under the pecan tree",2,"He'd like that",1,"He planted it, back in '79, said it'd outlive us all",2,"Looks like he was right, about that, at least"}},
{"fw_ld4_grief_a_0009","any",2,"reg=civilian,family,worker,rescue|hour=20,5|world=cold",{1,"Marcus would've hated this place",2,"He hated everywhere, remember? Too hot, too cold, too loud",1,"He complained about the sun",2,"He complained about the MOON",1,"...he'd have complained at his own funeral",2,"He'd have given the eulogy himself, to make sure it was right"}},
{"fw_ld4_grief_a_0010","any",2,"reg=civilian,family,worker,rescue",{1,"They're all gone, aren't they?",2,"Not all",1,"Almost",2,"But not all, and some are still out there, hoping we're alive",1,"...you really believe that",2,"I have to, don't you?"}},
{"fw_ld4_grief_a_0011","any",2,"reg=civilian,family,worker,rescue",{1,"I haven't cried yet",2,"That's okay",1,"Everyone keeps looking at me like I'm cold",2,"You're not cold, you're stunned",1,"How long does stunned last?",2,"As long as it needs to"}},
{"fw_ld4_grief_a_0012","any",2,"reg=civilian,family,worker,rescue",{1,"Hold my hand",2,"Of course",1,"Don't say anything",2,"I wasn't going to",1,"Good"}},
{"fw_ld4_grief_a_0013","any",2,"reg=civilian,family,worker,rescue",{1,"What do we say over a grave?",2,"I don't know, I'm not a preacher",1,"Then say what you feel",2,"...thank you, Dad, for everything, I'm sorry I wasn't there, I'm sorry I'm late",1,"That's perfect, that's exactly right"}},
{"fw_ld4_grief_a_0014","any",2,"reg=civilian,family,worker,rescue|world=door",{1,"I keep expecting her to walk in",2,"I know",1,"Every time the door moves, every single time",2,"Me too, me too, it never stops, does it?"}},
{"fw_ld4_grief_a_0015","any",2,"reg=civilian,family,worker,rescue",{1,"Do you pray?",2,"Not since the ninth",1,"Why not?",2,"Because I asked, and nobody answered",1,"Maybe they did, just not the way we wanted",2,"...that's an awful lot of maybe"}},
{"fw_ld4_grief_a_0016","any",2,"reg=law,swat|world=road",{1,"We lost another one",2,"Who?",1,"Reyes, on the north road, he got separated",2,"He had a baby coming, didn't he?",1,"Due in August, God, I don't even know how to tell his wife",2,"You tell her the truth, Frank, that's all you can do"}},
{"fw_ld4_grief_a_0017","any",2,"reg=law,swat",{1,"I keep his badge in my pocket",2,"Whose?",1,"Wilson's, from the night he didn't come back",2,"Why?",1,"So someone knows he served, so it's not just a number",2,"...give it here, let me look at it"}},
{"fw_ld4_grief_a_0018","any",2,"reg=law,swat",{1,"Another funeral",2,"This is the sixth this week",1,"Do you ever get used to it?",2,"No, and I hope I never do",1,"That's the only thing keeping me human"}},
{"fw_ld4_grief_a_0019","any",2,"reg=military,elite",{1,"I need a minute",2,"Take two",1,"He was a kid, Sarge",2,"They're all kids, Private, that's what makes it hard",1,"What do I do with that?",2,"You carry it, and you keep moving, and when you can't, you ask me to carry it"}},
{"fw_ld4_grief_a_0020","any",2,"reg=military,elite",{1,"Say it for me",2,"Say what?",1,"His name, the roll call, I can't",2,"Specialist Marcus Tillman",1,"Present",2,"...present"}},
{"fw_ld4_grief_a_0021","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"He was a pain in the ass, but he was OUR pain in the ass",2,"Yeah",1,"Who's gonna steal my smokes now?",2,"Nobody, nobody steals them anymore, and I hate it",1,"Me too, me too"}},
{"fw_ld4_grief_a_0022","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"You cryin'?",2,"No",1,"Your eyes are wet",2,"It's allergies",1,"You've never had allergies in your life",2,"...shut up, Marty"}},
{"fw_ld4_group_b_0001","any",2,"reg=civilian,family,worker,rescue|world=road",{1,"Who's the new guy?",2,"Found him on the road, says his name's Walt",1,"Can we trust him?",2,"He shared his water with the kid, that's good enough for now",1,"Keep an eye on him",2,"I will, I'm not stupid, I'm just tired of being suspicious"}},
{"fw_ld4_group_b_0002","any",2,"reg=civilian,family,worker,rescue",{1,"I think Darla's planning to leave",2,"What? Why?",1,"She's been packing her bag at night, quietly",2,"Should we stop her?",1,"No, but we should ask her why, and listen"}},
{"fw_ld4_group_b_0003","any",2,"reg=civilian,family,worker,rescue",{1,"Everybody, I have an announcement",2,"Oh God",1,"It's Maggie's birthday",2,"...and?",1,"I found a candle, a sad little candle, let's sing",2,"Happy birthday, Maggie, from the world's worst choir"}},
{"fw_ld4_group_b_0004","any",2,"reg=civilian,family,worker,rescue",{1,"He saved my life yesterday",2,"I know, I was there",1,"I never thanked him",2,"Then do it",1,"What if he thinks it's weird?",2,"He'll think it's weird, thank him anyway"}},
{"fw_ld4_group_b_0005","any",2,"reg=civilian,family,worker,rescue",{1,"I don't like how Pete looks at the food",2,"He's hungry",1,"We're all hungry, but he looks at it like it's his",2,"Let's talk to him, calmly, before it becomes a thing",1,"I'll do it, you stand next to me with a bat"}},
{"fw_ld4_group_b_0006","any",2,"reg=civilian,family,worker,rescue",{1,"We should have a vote",2,"On what?",1,"Whether we stay or go",2,"Stay, obviously",1,"Go, obviously",2,"Fine, let's count, hands up for stay",1,"...three to three, great, we're a democracy of idiots"}},
{"fw_ld4_group_b_0007","any",2,"reg=civilian,family,worker,rescue",{1,"I'm sorry I snapped at you earlier",2,"It's fine",1,"No, it's not, I was scared, and I took it out on you",2,"Me too, honestly, can we hug now?",1,"Yes, yes, please"}},
{"fw_ld4_group_b_0008","any",2,"reg=civilian,family,worker,rescue",{1,"Anyone seen Luke?",2,"He went to check the perimeter",1,"When?",2,"An hour ago",1,"He's late, he's never late",2,"I'll go look, you stay here, and don't panic"}},
{"fw_ld4_group_b_0009","any",2,"reg=civilian,family,worker,rescue",{1,"Look who's back!",2,"Luke! You scared the hell out of us!",1,"Sorry, got turned around, found something, though",2,"What?",1,"A whole case of canned peaches",2,"You're forgiven, you magnificent bastard"}},
{"fw_ld4_group_b_0010","any",2,"reg=civilian,family,worker,rescue",{1,"I want to say something",2,"Go ahead",1,"I'm glad you're all here",2,"Aw",1,"I mean it, I'd be dead without you",2,"Stop, you're going to make me cry, and I need my strength"}},
{"fw_ld4_group_b_0011","any",2,"reg=civilian,family,worker,rescue",{1,"What if we're the last ones?",2,"We're not",1,"But what if?",2,"Then we're the last ones, and we make the best of it",1,"That's not comforting",2,"Wasn't trying to comfort you, just being straight"}},
{"fw_ld4_group_b_0012","any",2,"reg=civilian,family,worker,rescue",{1,"This group is falling apart",2,"Don't say that",1,"I keep thinking of Jim drinking, Sally not saying a word, the kids frightened. Like that old group all over again",2,"We hold it together, that's all we can do",1,"How?",2,"One meal, one night, one person talking to another. That's as far as I can look"}},
{"fw_ld4_group_b_0013","any",2,"reg=civilian,family,worker,rescue",{1,"I talk to my wife at night",2,"In your head?",1,"Out loud, softly, she answers, sometimes",2,"Does it help?",1,"It helps me sleep, that's all I need"}},
{"fw_ld4_group_b_0014","any",2,"reg=civilian,family,worker,rescue",{1,"Did you hear the kid laugh?",2,"When?",1,"Just now, at the dog",2,"We have a dog?",1,"A stray, followed us from the last town",2,"Let's keep him, the kid laughed, that's worth a dog"}},
{"fw_ld4_group_b_0015","any",2,"reg=civilian,family,worker,rescue",{1,"I trust you",2,"Why?",1,"Because you could've left me, and you didn't",2,"...that's a good reason"}},
{"fw_ld4_group_b_0016","any",2,"reg=civilian,family,worker,rescue|tmp=fresh",{1,"I'm sorry I'm such a mess",2,"You're not a mess",1,"I cried in front of everyone",2,"So did I, so did half the group, it's allowed",1,"Really?",2,"Really, you're doing fine, you're doing better than fine"}},
{"fw_ld4_group_b_0017","any",2,"reg=civilian,family,worker,rescue|tmp=fresh",{1,"Do you think they like me?",2,"Who?",1,"The group, I feel like they tolerate me",2,"They like you, you make them laugh",1,"By accident",2,"That counts"}},
{"fw_ld4_group_b_0018","any",2,"reg=law,swat",{1,"The new recruit froze today",2,"Happens",1,"He could've gotten someone killed",2,"Then train him, don't bury him",1,"You're too soft",2,"And you're too hard, together we're a decent cop"}},
{"fw_ld4_group_b_0019","any",2,"reg=law,swat",{1,"Morale check, how's the team?",2,"Quiet",1,"Quiet's bad",2,"Quiet's better than fighting",1,"Fair, keep me posted"}},
{"fw_ld4_group_b_0020","any",2,"reg=military,elite|hour=4,9",{1,"Fresh troops arrived",2,"How many?",1,"Four, scared, hungry, one with a limp",2,"Get them chow, get them cots, we'll brief at dawn",1,"Yes sir"}},
{"fw_ld4_group_b_0021","any",2,"reg=military,elite",{1,"Corporal, you're limping",2,"Twisted my ankle, sir",1,"Is it broken?",2,"Don't think so",1,"Wrap it, and stay off it tomorrow, that's an order"}},
{"fw_ld4_group_b_0022","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"Remember that newbie who wanted in?",2,"Said he could do anything",1,"What could he do?",2,"He said he could shoot",1,"You had him shoot at a can, didn't you?",2,"Missed the can. Admitted it. That was why I liked him"}},
{"fw_ld4_group_b_0023","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"We should split up",2,"Why?",1,"Too many of us in one place, too easy to hit",2,"And if one gets caught?",1,"Then one gets caught, the rest eat well"}},
{"fw_ld4_group_b_0024","any",2,"reg=family",{1,"Come on, everyone, supper's ready",2,"Coming, Mama",1,"Wash your hands first",2,"With what, there's no soap",1,"With water and love, now go"}},
{"fw_ld4_group_b_0025","any",2,"reg=family",{1,"Papa's been quiet today",2,"He's tired",1,"He's sad",2,"He's both, give him time, and a hug",1,"I'll hug him, he never says no to a hug"}},
{"fw_ld4_haggle_a_0001","any",2,"reg=civilian,family,worker,rescue",{1,"What would you ask for a flashlight? Two cans of corn?",2,"For a Maglite? I'd ask four, at least",1,"Even if it had a dent?",2,"The dent would be character. Three and a pack of gum",1,"Two and a half, that's my imaginary final offer",2,"Even in pretend trades you rob me"}},
{"fw_ld4_haggle_a_0002","any",2,"reg=civilian,family,worker,rescue",{1,"What do you want for the aspirin?",2,"What have you got?",1,"Socks, a lighter, half a bottle of peroxide",2,"The lighter, and you owe me a favor",1,"A favor? What kind?",2,"I'll tell you when I need it, that's how favors work"}},
{"fw_ld4_haggle_a_0003","any",2,"reg=civilian,family,worker,rescue",{1,"What would real coffee be worth to you?",2,"Folgers, never opened?",1,"How much?",2,"Name your price",1,"I'd have to empty my pockets",2,"I mean what would you part with?",1,"Anything but a picture of my dog",2,"Keep the dog. I'd rather hear the story behind the picture"}},
{"fw_ld4_haggle_a_0004","any",2,"reg=civilian,family,worker,rescue",{1,"Three batteries for a can of tuna?",2,"Are they good batteries?",1,"Duracell, from the old days",2,"Test them",1,"They work! See the little light? Right there",2,"Fine, tuna's yours"}},
{"fw_ld4_haggle_a_0005","any",2,"reg=civilian,family,worker,rescue",{1,"Fresh eggs, who wants fresh eggs?",2,"How many?",1,"Six, I'll trade them for a pack of cigarettes",2,"I don't have cigarettes",1,"What do you have?",2,"A paperback, a really good paperback",1,"Western?",2,"Romance, with a cowboy",1,"...deal"}},
{"fw_ld4_haggle_a_0006","any",2,"reg=civilian,family,worker,rescue",{1,"Ever have somebody ask you to treat a tooth because you were a vet?",2,"More than once",1,"They figured a sore tooth was close enough?",2,"People hear doctor and stop asking what kind. I wouldn't pull a person's tooth with pliers and a bottle",1,"Did they offer to pay you?",2,"Sometimes. Didn't make it something I was qualified to do"}},
{"fw_ld4_haggle_a_0007","any",2,"reg=civilian,family,worker,rescue",{1,"You're robbing me",2,"I'm negotiating",1,"With a knife?",2,"It's a very convincing knife",1,"...fine, take the damn socks"}},
{"fw_ld4_haggle_a_0008","any",2,"reg=civilian,family,worker,rescue|world=summer",{1,"Anyone want to trade a coat for a bag of rice?",2,"How warm is it?",1,"Warmer than rice",2,"That doesn't answer it",1,"It's summer, who needs a coat? You need rice"}},
{"fw_ld4_haggle_a_0009","any",2,"reg=civilian,family,worker,rescue",{1,"I found a deck of cards",2,"Where?",1,"In a dead man's pocket, I feel bad about it",2,"Don't, he'd want them used, deal me in",1,"Gin or poker?",2,"Whatever cheats better"}},
{"fw_ld4_haggle_a_0010","any",2,"reg=civilian,family,worker,rescue",{1,"Would you trade a candle for a pen?",2,"A pen? What will I do with a pen?",1,"Write down all the things we lost",2,"I'd consider it. I've got a list in my head already"}},
{"fw_ld4_haggle_a_0011","any",2,"reg=civilian,family,worker,rescue",{1,"Five bullets for that bottle of whiskey",2,"It's not for sale",1,"Everything's for sale",2,"Not Dad's whiskey",1,"...yeah, fine, forget I asked"}},
{"fw_ld4_haggle_a_0012","any",2,"reg=civilian,family,worker,rescue",{1,"Spare a smoke?",2,"Last one",1,"Come on, I'll owe you",2,"You say that every time",1,"And every time I mean it",2,"Half, then, and you owe me a whole one"}},
{"fw_ld4_haggle_a_0013","any",2,"reg=civilian,family,worker,rescue|tmp=fresh",{1,"If somebody offered you a candy bar, would you trust them?",2,"Is it a trap?",1,"Suppose it was just a candy bar",2,"...how much?",1,"Nothing. Suppose they thought you needed it",2,"I'd probably cry. Then I'd ask why they were being so kind"}},
{"fw_ld4_haggle_a_0014","any",2,"reg=law,swat",{1,"You got a spare mag?",2,"I've got one, why?",1,"Mine's empty, I'll trade you my MRE",2,"Beef stew?",1,"Chili mac",2,"...deal, but I want the little candy packet too",1,"Greedy"}},
{"fw_ld4_haggle_a_0015","any",2,"reg=law,swat",{1,"How much is a case of water worth these days?",2,"Depends, a gun?",1,"Not that much",2,"A pair of boots?",1,"Boots are a start"}},
{"fw_ld4_haggle_a_0016","any",2,"reg=military,elite",{1,"Anyone got a spare pair of socks?",2,"For what?",1,"My feet are rotting",2,"I'll trade you for chocolate",1,"I don't have chocolate",2,"Then you'll rot, Private"}},
{"fw_ld4_haggle_a_0017","any",2,"reg=military,elite",{1,"I'll trade my MRE for your MRE",2,"Why?",1,"Yours has the good cookie",2,"No deal, it's my cookie",1,"Come on!",2,"Fight me, Smith"}},
{"fw_ld4_haggle_a_0018","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"Tell you what, I'll sell you protection",2,"From what?",1,"From me",2,"...how much?",1,"Everything, plus interest"}},
{"fw_ld4_haggle_a_0019","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"That's my knife",2,"It was your knife",1,"Give it back",2,"What are you gonna give me?",1,"A bruise",2,"...fair, here, it's a crummy knife anyway"}},
{"fw_ld4_haggle_a_0020","any",2,"reg=family",{1,"Mrs. Adams, I'll trade you a jar of peaches for some thread",2,"How many peaches?",1,"One jar, a good one",2,"And what thread?",1,"Black, I need to mend Papa's shirt",2,"Here you go, and thank you for the peaches"}},
{"fw_ld4_haggle_a_0021","any",2,"reg=family",{1,"Grandpa, can I trade my baseball card?",2,"For what, child?",1,"For a cookie",2,"Which card?",1,"Hank Aaron, 1974",2,"...we're not trading that, I'll find you a cookie"}},
{"fw_ld4_jokes_a_0001","any",2,"reg=civilian,family,worker,rescue",{1,"Knock knock",2,"Who's there?",1,"Not a zombie",2,"Not a zombie who?",1,"See, that's the joke, you can't tell, ha",2,"I hate you so much"}},
{"fw_ld4_jokes_a_0002","any",2,"reg=civilian,family,worker,rescue|world=road",{1,"Why did the survivor cross the road?",2,"Why?",1,"Because there was a horde on the other side, and he was the dumb one",2,"Ha- that's just Tuesday"}},
{"fw_ld4_jokes_a_0003","any",2,"reg=civilian,family,worker,rescue",{1,"What's the difference between me and a zombie?",2,"What?",1,"I still have to shave",2,"Is that all?",1,"Hey, I pay attention to details"}},
{"fw_ld4_jokes_a_0004","any",2,"reg=civilian,family,worker,rescue",{1,"If I die, promise you'll put something funny on my grave",2,"Like what?",1,"'Here lies Gary, he said it was nothing'",2,"Gary, you say that about everything",1,"That's the joke, Dave"}},
{"fw_ld4_jokes_a_0005","any",2,"reg=civilian,family,worker,rescue",{1,"I told my wife she was drawing her eyebrows too high",2,"How'd that go?",1,"She looked surprised",2,"Where is she now?",1,"Out of earshot, thankfully, I'm not suicidal"}},
{"fw_ld4_jokes_a_0006","any",2,"reg=civilian,family,worker,rescue",{1,"What do you call a zombie in a bow tie?",2,"What?",1,"Formally dead, ha",2,"Terrible, just terrible"}},
{"fw_ld4_jokes_a_0007","any",2,"reg=civilian,family,worker,rescue",{1,"Our boy's school had a motto, 'Learn today, lead tomorrow'",2,"So?",1,"There's no tomorrow, so I guess we've got a lot of learning left",2,"And no leading",1,"Exactly, ha"}},
{"fw_ld4_jokes_a_0008","any",2,"reg=civilian,family,worker,rescue|hour=20,5",{1,"My horoscope said, 'Today is a good day for adventure'",2,"Did you check the date?",1,"It's the same horoscope as yesterday, ha, they never learn",2,"Maybe the stars are dead too"}},
{"fw_ld4_jokes_a_0009","any",2,"reg=civilian,family,worker,rescue",{1,"What's brown and sticky?",2,"A stick",1,"No, a dozen cans of expired chili",2,"Hey, don't joke, that's my dinner"}},
{"fw_ld4_jokes_a_0010","any",2,"reg=civilian,family,worker,rescue",{1,"Did you hear the one about the optimist?",2,"No",1,"Neither did I, he's gone",2,"...that's dark, even for you"}},
{"fw_ld4_jokes_a_0011","any",2,"reg=civilian,family,worker,rescue",{1,"Do you smell something?",2,"Yeah",1,"Is it me?",2,"It's us, it's all of us, we haven't had a bath in a week",1,"I can't smell it anymore, that's a bad sign"}},
{"fw_ld4_jokes_a_0012","any",2,"reg=civilian,family,worker,rescue",{1,"Knock knock",2,"Who's there?",1,"Boo",2,"Boo who?",1,"Why are you crying? It's just a joke",2,"I'm not crying, you're crying"}},
{"fw_ld4_jokes_a_0013","any",2,"reg=civilian,family,worker,rescue",{1,"I think my shoes are alive",2,"They squeak, don't they?",1,"Every step, 'squeak, squeak, here I am'",2,"We've got a built-in warning system, it's called your feet"}},
{"fw_ld4_jokes_a_0014","any",2,"reg=law,swat",{1,"Hey, what do you call a deputy with no gun?",2,"What?",1,"A crossing guard",2,"Hey, that's rude to crossing guards",1,"Say that to their face"}},
{"fw_ld4_jokes_a_0015","any",2,"reg=law,swat",{1,"Know what's better than a donut?",2,"What?",1,"Another donut",2,"Nothing, I said nothing",1,"I've been saving that one for six weeks, thank you for your silence"}},
{"fw_ld4_jokes_a_0016","any",2,"reg=law,swat",{1,"Officer, I can explain",2,"Explain what?",1,"The thing, the thing I did, I'm practicing",2,"Who for?",1,"The first person I meet who's not trying to eat me"}},
{"fw_ld4_jokes_a_0017","any",2,"reg=military,elite",{1,"What do you call a hungry Marine?",2,"What?",1,"A Marine",2,"That's not funny",1,"It is if you've met one"}},
{"fw_ld4_jokes_a_0018","any",2,"reg=military,elite",{1,"Private, why's your boot untied?",2,"It's tied, sir",1,"Then why does it look like it isn't?",2,"Because it's ugly, sir",1,"...that's the funniest thing I've heard all week, carry on"}},
{"fw_ld4_jokes_a_0019","any",2,"reg=military,elite",{1,"Army says, 'Be all you can be'",2,"What can we be?",1,"Hungry, mostly",2,"And tired",1,"And bitten, hopefully not"}},
{"fw_ld4_jokes_a_0020","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"What's the difference between me and a cop?",2,"What?",1,"I steal from people that deserve it",2,"And?",1,"Okay, I steal from everybody, but I look better doing it"}},
{"fw_ld4_jokes_a_0021","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"Hey, you know what I hate about this new world?",2,"What?",1,"No more bail bondsmen",2,"Why do you care?",1,"I was in the middle of a lovely court case"}},
{"fw_ld4_jokes_a_0022","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"Hey, Tommy, what's the plan?",2,"Rob 'em first, shoot 'em if that fails, and if that fails too, hide",1,"What if A and B fail?",2,"Then it's plan D: pray",1,"Does C work?",2,"Never tried it, I'm not that smart"}},
{"fw_ld4_jokes_a_0023","any",2,"reg=family|world=road",{1,"Papa, why did the chicken cross the road?",2,"To get away from the farmer?",1,"No, Papa, to get to the other side",2,"Well, that's the best reason I've heard"}},
{"fw_ld4_jokes_a_0024","any",2,"reg=family",{1,"Grandma, are you laughing?",2,"I'm coughing, child",1,"You're laughing",2,"I'm coughing with joy",1,"Tell me another one"}},
{"fw_ld4_misc_c_0001","any",2,"reg=civilian,family,worker,rescue",{1,"I can't feel my toes",2,"Wiggle them",1,"They're not responding",2,"Take your boot off, let me look",1,"If I take it off, I'll never get it back on",2,"Then we carry you, simple as that"}},
{"fw_ld4_misc_c_0002","any",2,"reg=civilian,family,worker,rescue",{1,"What if we just stayed here forever?",2,"Here?",1,"Why not? It's quiet, mostly",2,"Mostly is doing a lot of work in that sentence"}},
}
